-- Type of CASE over each pair of integer types, and with a NULL literal, for the merge
-- rules of the builder; UNION ALL of the same pairs.
DROP TABLE IF EXISTS ci_src;
DROP TABLE IF EXISTS ci_case;
DROP TABLE IF EXISTS ci_union;
CREATE TABLE ci_src (c_t TINYINT NULL, c_tu TINYINT UNSIGNED NULL, c_s SMALLINT NULL, c_su SMALLINT UNSIGNED NULL, c_m MEDIUMINT NULL, c_mu MEDIUMINT UNSIGNED NULL, c_i INT NULL, c_iu INT UNSIGNED NULL, c_b BIGINT NULL, c_bu BIGINT UNSIGNED NULL, k INT NULL);
INSERT INTO ci_src (k) VALUES (1);
CREATE TABLE ci_case AS SELECT CASE WHEN k > 0 THEN c_t ELSE c_t END AS t_t, CASE WHEN k > 0 THEN c_t ELSE c_tu END AS t_tu, CASE WHEN k > 0 THEN c_t ELSE c_s END AS t_s, CASE WHEN k > 0 THEN c_t ELSE c_su END AS t_su, CASE WHEN k > 0 THEN c_t ELSE c_m END AS t_m, CASE WHEN k > 0 THEN c_t ELSE c_mu END AS t_mu, CASE WHEN k > 0 THEN c_t ELSE c_i END AS t_i, CASE WHEN k > 0 THEN c_t ELSE c_iu END AS t_iu, CASE WHEN k > 0 THEN c_t ELSE c_b END AS t_b, CASE WHEN k > 0 THEN c_t ELSE c_bu END AS t_bu, CASE WHEN k > 0 THEN c_t ELSE NULL END AS t_null, CASE WHEN k > 0 THEN c_tu ELSE c_tu END AS tu_tu, CASE WHEN k > 0 THEN c_tu ELSE c_s END AS tu_s, CASE WHEN k > 0 THEN c_tu ELSE c_su END AS tu_su, CASE WHEN k > 0 THEN c_tu ELSE c_m END AS tu_m, CASE WHEN k > 0 THEN c_tu ELSE c_mu END AS tu_mu, CASE WHEN k > 0 THEN c_tu ELSE c_i END AS tu_i, CASE WHEN k > 0 THEN c_tu ELSE c_iu END AS tu_iu, CASE WHEN k > 0 THEN c_tu ELSE c_b END AS tu_b, CASE WHEN k > 0 THEN c_tu ELSE c_bu END AS tu_bu, CASE WHEN k > 0 THEN c_tu ELSE NULL END AS tu_null, CASE WHEN k > 0 THEN c_s ELSE c_s END AS s_s, CASE WHEN k > 0 THEN c_s ELSE c_su END AS s_su, CASE WHEN k > 0 THEN c_s ELSE c_m END AS s_m, CASE WHEN k > 0 THEN c_s ELSE c_mu END AS s_mu, CASE WHEN k > 0 THEN c_s ELSE c_i END AS s_i, CASE WHEN k > 0 THEN c_s ELSE c_iu END AS s_iu, CASE WHEN k > 0 THEN c_s ELSE c_b END AS s_b, CASE WHEN k > 0 THEN c_s ELSE c_bu END AS s_bu, CASE WHEN k > 0 THEN c_s ELSE NULL END AS s_null, CASE WHEN k > 0 THEN c_su ELSE c_su END AS su_su, CASE WHEN k > 0 THEN c_su ELSE c_m END AS su_m, CASE WHEN k > 0 THEN c_su ELSE c_mu END AS su_mu, CASE WHEN k > 0 THEN c_su ELSE c_i END AS su_i, CASE WHEN k > 0 THEN c_su ELSE c_iu END AS su_iu, CASE WHEN k > 0 THEN c_su ELSE c_b END AS su_b, CASE WHEN k > 0 THEN c_su ELSE c_bu END AS su_bu, CASE WHEN k > 0 THEN c_su ELSE NULL END AS su_null, CASE WHEN k > 0 THEN c_m ELSE c_m END AS m_m, CASE WHEN k > 0 THEN c_m ELSE c_mu END AS m_mu, CASE WHEN k > 0 THEN c_m ELSE c_i END AS m_i, CASE WHEN k > 0 THEN c_m ELSE c_iu END AS m_iu, CASE WHEN k > 0 THEN c_m ELSE c_b END AS m_b, CASE WHEN k > 0 THEN c_m ELSE c_bu END AS m_bu, CASE WHEN k > 0 THEN c_m ELSE NULL END AS m_null, CASE WHEN k > 0 THEN c_mu ELSE c_mu END AS mu_mu, CASE WHEN k > 0 THEN c_mu ELSE c_i END AS mu_i, CASE WHEN k > 0 THEN c_mu ELSE c_iu END AS mu_iu, CASE WHEN k > 0 THEN c_mu ELSE c_b END AS mu_b, CASE WHEN k > 0 THEN c_mu ELSE c_bu END AS mu_bu, CASE WHEN k > 0 THEN c_mu ELSE NULL END AS mu_null, CASE WHEN k > 0 THEN c_i ELSE c_i END AS i_i, CASE WHEN k > 0 THEN c_i ELSE c_iu END AS i_iu, CASE WHEN k > 0 THEN c_i ELSE c_b END AS i_b, CASE WHEN k > 0 THEN c_i ELSE c_bu END AS i_bu, CASE WHEN k > 0 THEN c_i ELSE NULL END AS i_null, CASE WHEN k > 0 THEN c_iu ELSE c_iu END AS iu_iu, CASE WHEN k > 0 THEN c_iu ELSE c_b END AS iu_b, CASE WHEN k > 0 THEN c_iu ELSE c_bu END AS iu_bu, CASE WHEN k > 0 THEN c_iu ELSE NULL END AS iu_null, CASE WHEN k > 0 THEN c_b ELSE c_b END AS b_b, CASE WHEN k > 0 THEN c_b ELSE c_bu END AS b_bu, CASE WHEN k > 0 THEN c_b ELSE NULL END AS b_null, CASE WHEN k > 0 THEN c_bu ELSE c_bu END AS bu_bu, CASE WHEN k > 0 THEN c_bu ELSE NULL END AS bu_null FROM ci_src;
SELECT COLUMN_NAME, COLUMN_TYPE FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'ci_case' ORDER BY ORDINAL_POSITION;
CREATE TABLE ci_union AS SELECT c_t AS u_t_tu, c_t AS u_t_s, c_t AS u_t_su, c_t AS u_t_m, c_t AS u_t_mu, c_t AS u_t_i, c_t AS u_t_iu, c_t AS u_t_b, c_t AS u_t_bu, c_t AS u_t_null, c_tu AS u_tu_s, c_tu AS u_tu_su, c_tu AS u_tu_m, c_tu AS u_tu_mu, c_tu AS u_tu_i, c_tu AS u_tu_iu, c_tu AS u_tu_b, c_tu AS u_tu_bu, c_tu AS u_tu_null, c_s AS u_s_su, c_s AS u_s_m, c_s AS u_s_mu, c_s AS u_s_i, c_s AS u_s_iu, c_s AS u_s_b, c_s AS u_s_bu, c_s AS u_s_null, c_su AS u_su_m, c_su AS u_su_mu, c_su AS u_su_i, c_su AS u_su_iu, c_su AS u_su_b, c_su AS u_su_bu, c_su AS u_su_null, c_m AS u_m_mu, c_m AS u_m_i, c_m AS u_m_iu, c_m AS u_m_b, c_m AS u_m_bu, c_m AS u_m_null, c_mu AS u_mu_i, c_mu AS u_mu_iu, c_mu AS u_mu_b, c_mu AS u_mu_bu, c_mu AS u_mu_null, c_i AS u_i_iu, c_i AS u_i_b, c_i AS u_i_bu, c_i AS u_i_null, c_iu AS u_iu_b, c_iu AS u_iu_bu, c_iu AS u_iu_null, c_b AS u_b_bu, c_b AS u_b_null, c_bu AS u_bu_null FROM ci_src UNION ALL SELECT c_tu, c_s, c_su, c_m, c_mu, c_i, c_iu, c_b, c_bu, NULL, c_s, c_su, c_m, c_mu, c_i, c_iu, c_b, c_bu, NULL, c_su, c_m, c_mu, c_i, c_iu, c_b, c_bu, NULL, c_m, c_mu, c_i, c_iu, c_b, c_bu, NULL, c_mu, c_i, c_iu, c_b, c_bu, NULL, c_i, c_iu, c_b, c_bu, NULL, c_iu, c_b, c_bu, NULL, c_b, c_bu, NULL, c_bu, NULL, NULL FROM ci_src;
SELECT COLUMN_NAME, COLUMN_TYPE FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'ci_union' ORDER BY ORDINAL_POSITION;
DROP TABLE ci_case;
DROP TABLE ci_union;
DROP TABLE ci_src;
